package top.wkbin.taixu.core.database

import androidx.room.testing.MigrationTestHelper
import androidx.sqlite.db.framework.FrameworkSQLiteOpenHelperFactory
import androidx.test.platform.app.InstrumentationRegistry
import org.junit.Assert.*
import org.junit.Rule
import org.junit.Test
import org.junit.runner.RunWith
import org.robolectric.RobolectricTestRunner
import org.robolectric.annotation.Config

/** 85 is the inspected source schema; 86 must be generated by Room KSP, never hand-authored. */
@RunWith(RobolectricTestRunner::class)
@Config(sdk = [34])
class TeamCommunicationMigrationTest {
    @get:Rule val helper = MigrationTestHelper(InstrumentationRegistry.getInstrumentation(), AppDatabase::class.java,
        emptyList(), FrameworkSQLiteOpenHelperFactory())

    @Test(timeout = 20_000) fun migrationCreatesDurableLedgerWithoutFabricatedSchema() {
        val path = InstrumentationRegistry.getInstrumentation().targetContext.getDatabasePath("communication-85-86").absolutePath
        helper.createDatabase(path, 85).close()
        helper.runMigrationsAndValidate(path, 86, true, MIGRATION_85_86).use { db ->
            db.query("SELECT COUNT(*) FROM team_communication_policy").use { assertTrue(it.moveToFirst()); assertEquals(0, it.getInt(0)) }
            db.query("SELECT COUNT(*) FROM team_communication_messages").use { assertTrue(it.moveToFirst()); assertEquals(0, it.getInt(0)) }
            db.query("PRAGMA foreign_key_check").use { assertFalse(it.moveToFirst()) }
        }
    }

    @Test(timeout = 20_000) fun acceptedLegacyRequestsPreserveDeliveryOrderAndNeverReplayOrRecharge() {
        val path = InstrumentationRegistry.getInstrumentation().targetContext
            .getDatabasePath("communication-legacy-85-86").absolutePath
        helper.createDatabase(path, 85).use { db ->
            // Required v85 fields are explicit; Kotlin constructor defaults are NOT SQL defaults.
            db.execSQL("INSERT INTO persona_bots(id,name,role,systemPrompt,avatarSeed,sessionId,isMainBot,colorHex,createdAt,updatedAt) VALUES ('a','A','role','','a','dm-a',0,'#000000',1,1)")
            db.execSQL("INSERT INTO group_chats(id,name,adminBotId,description,createdAt,background) VALUES ('g','G','a','',1,'default')")
            db.execSQL("INSERT INTO harness_sessions(id,title,createdAt,updatedAt,workspace,projectType,approvalMode) VALUES ('s','S',1,1,'/workspace','other','assisted')")
            db.execSQL("INSERT INTO bot_assignments(id,groupId,botId,botName,title,task,status,writePathsJson,createdAt,startedAt,sessionId,independent,teamBinding) VALUES ('target','g','a','A','T','task','RUNNING','[]',1,1,'s',1,'team@1')")
            // Reverse lexical IDs AND timestamps to expose accidental createdAt/id sorting.
            listOf("pending", "running", "completed", "admitted", "cancelled").forEachIndexed { index, status ->
                val id = "peer:${5-index}"
                db.execSQL("INSERT INTO bot_assignment_requests(id,assignmentId,instruction,createdAt,status,artifactsJson) VALUES (?,'target',?,?,?,'[]')",
                    arrayOf<Any?>(id, """{"sourceAssignmentId":"source","sourceMemberId":"a","hop":1}""", 100L-index, status))
            }
        }
        helper.runMigrationsAndValidate(path, 86, true, MIGRATION_85_86).use { db ->
            repeat(2) {
                if (it == 1) MIGRATION_85_86.migrate(db) // INSERT OR IGNORE must not double charge.
                db.query("SELECT id,deliverySequence,state FROM team_communication_messages ORDER BY deliverySequence").use { c ->
                    repeat(5) { index ->
                        assertTrue(c.moveToNext())
                        assertEquals("peer:${5-index}", c.getString(0))
                        assertEquals(index + 1L, c.getLong(1))
                        assertEquals(if (index == 4) "cancelled" else "queued", c.getString(2))
                    }
                    assertFalse(c.moveToNext())
                }
                db.query("SELECT COUNT(*) FROM team_communication_messages WHERE chargedAt IS NOT NULL").use { c ->
                    assertTrue(c.moveToFirst()); assertEquals(5, c.getInt(0))
                }
                db.query("SELECT status FROM bot_assignment_requests ORDER BY rowid").use { c ->
                    for (status in listOf("pending", "running", "completed", "admitted", "cancelled")) {
                        assertTrue(c.moveToNext()); assertEquals(status, c.getString(0))
                    }
                    assertFalse(c.moveToNext())
                }
            }
            db.query("PRAGMA foreign_key_check").use { assertFalse(it.moveToFirst()) }
        }
    }

}
